  static void Road(Route route,bool lines=true){var v=new List<Vector3>();var ix=new List<int>();var lv=new List<Vector3>();var li=new List<int>();float walked=0;var pts=route.points.Select(p=>p.V).ToArray();Vector3 Surface(Vector3 p,float y=.09f){p.y=Ground(p)+y;return p;}Vector3 Side(int i){var dir=pts[Mathf.Min(i+1,pts.Length-1)]-pts[Mathf.Max(i-1,0)];return Vector3.Cross(Vector3.up,dir.normalized);}
   for(int i=0;i<pts.Length-1;i++){var a=pts[i];var b=pts[i+1];float length=Vector3.Distance(a,b);if(length<.0001f)continue;var sa=Side(i);var sb=Side(i+1);int columns=Mathf.CeilToInt(route.width/2);for(int j=0;j<columns;j++){float u=j/(float)columns*2-1,w=(j+1f)/columns*2-1;Quad(v,ix,Surface(a+sa*u*route.width*.5f),Surface(b+sb*u*route.width*.5f),Surface(b+sb*w*route.width*.5f),Surface(a+sa*w*route.width*.5f));}if(lines&&walked%8<2.5f&&length>.25f){var forward=(b-a).normalized;var end=a+forward*Mathf.Min(1.5f,length);Quad(lv,li,Surface(a-sa*.075f,.105f),Surface(end-sa*.075f,.105f),Surface(end+sa*.075f,.105f),Surface(a+sa*.075f,.105f));}walked+=length;}
