  static void Mountains(){for(int i=0;i<16;i++){float a=(i*22.5f+8)*Mathf.Deg2Rad;string slug="Mountain_"+(i%8+1).ToString("D2");var entry=AlpsRebuildAssets.Find(slug);float target=125+(i%3)*12;float scale=target/Mathf.Max(entry.localBounds.size.x,entry.localBounds.size.z);var p=new Vector3(Mathf.Sin(a)*420,0,Mathf.Cos(a)*420);var g=Instance(slug,mountains,"Mountain "+(i+1).ToString("D2")+" | "+slug,p,i*37%360,scale);NaturalMountain(g,Root);}}
  static string NaturalMountain(GameObject g,string folder){
