  public static void Refine(){
   scene=SceneManager.GetActiveScene();Check(scene.path==PathName&&!scene.isDirty&&!EditorApplication.isPlaying,"clean Alps before refinement");string backup=Log+"/Before-clearance-refine.unity";File.Copy(PathName,backup,true);
   try{
    Root=System.IO.Path.GetDirectoryName(AssetDatabase.GetAssetPath(All<SnowField>(scene).Single().seed)).Replace('\\','/');
    terrainMesh=All<CatalogPlacement>(scene).Single(p=>p.assetId=="alps-rebuild-terrainbase").GetComponentInChildren<MeshCollider>();
    roads=All<Transform>(scene).Single(t=>t.name.StartsWith("03 Roads"));asphalt=roads.GetComponentsInChildren<MeshRenderer>().First(r=>r.GetComponent<MeshCollider>()).sharedMaterial;marking=roads.GetComponentsInChildren<MeshRenderer>().First(r=>r.name.Contains("yellow centre")).sharedMaterial;
    plan=JsonUtility.FromJson<Plan>(File.ReadAllText("SourceAssets/AlpsRebuild/LayoutPlan.json"));meshId=500;
    foreach(var t in roads.Cast<Transform>().Where(t=>t.name.StartsWith("Southern neighbourhood loop")).ToArray())UnityEngine.Object.DestroyImmediate(t.gameObject);Road(plan.roads.Single(r=>r.name.StartsWith("Southern neighbourhood loop")));
    var furniture=All<Transform>(scene).Single(t=>t.name.StartsWith("07 Street furniture"));
    foreach(Transform t in furniture.Cast<Transform>().ToArray()){
     if(t.name=="Snow depot board")t.position=new Vector3(-113,Ground(new Vector3(-113,0,-74)),-74);
     if(t.name=="Fuel and repair board")t.position=new Vector3(-125,Ground(new Vector3(-125,0,-74)),-74);
     if(t.name=="Street lamp 24"){t.position=new Vector3(124,0,-18);Seat(t.gameObject);}
     if(t.name.StartsWith("Street lamp")&&t.position.x>-125&&t.position.x<-60&&t.position.z>-125&&t.position.z<-70)UnityEngine.Object.DestroyImmediate(t.gameObject);
    }
    Physics.SyncTransforms();var field=All<SnowField>(scene).Single();var previous=field.seed;var revised=UnityEngine.Object.Instantiate(previous);for(int i=0;i<revised.grid.blocked.Length;i++)revised.grid.blocked[i]=Physics.CheckBox(new Vector3(revised.grid.X(i),SnowField.Ground+.85f,revised.grid.Z(i)),new Vector3(.22f,.65f,.22f),Quaternion.identity,1,QueryTriggerInteraction.Ignore);AssetDatabase.CreateAsset(revised,AssetDatabase.GenerateUniqueAssetPath(Root+"/ClearanceSnowSeed.asset"));field.seed=revised;EditorUtility.SetDirty(field);AssetDatabase.SaveAssets();Validate(scene);Check(EditorSceneManager.SaveScene(scene),"save clearance refinement");scene=EditorSceneManager.OpenScene(PathName);Audit();Capture(scene);EditorSceneManager.OpenScene(PathName);File.WriteAllText(Log+"/Refinement.txt","Saved/reopened targeted road and furniture clearance correction; snow depth/credit unchanged. See ClearanceAudit.txt and final captures.");
   }catch{if(SceneManager.GetActiveScene().isDirty)EditorSceneManager.SaveScene(SceneManager.GetActiveScene(),Log+"/Failed-refinement.unity",true);File.Copy(backup,PathName,true);AssetDatabase.ImportAsset(PathName,ImportAssetOptions.ForceUpdate);EditorSceneManager.OpenScene(PathName);throw;}
  }
  public static void Audit(){
   var s=SceneManager.GetActiveScene();Check(s.path==PathName&&!s.isDirty&&!EditorApplication.isPlaying,"clean rebuilt scene for audit");
   terrainMesh=All<CatalogPlacement>(s).Single(p=>p.assetId=="alps-rebuild-terrainbase").GetComponentInChildren<MeshCollider>();
   var data=JsonUtility.FromJson<Plan>(File.ReadAllText("SourceAssets/AlpsRebuild/LayoutPlan.json"));Physics.SyncTransforms();
   var report=new System.Text.StringBuilder();int samples=0,blocked=0;
   bool Obstacle(Collider c)=>c.enabled&&!c.isTrigger&&c.gameObject.activeInHierarchy&&c!=terrainMesh&&!c.GetComponentInParent<MachineController>()&&!c.GetComponentInParent<SnowField>()&&!c.GetComponentInParent<Terrain>()&&!Parents(c.transform).Any(t=>t.name.StartsWith("03 Roads"));
   var routes=data.roads.ToList();
   Point[] Line(float x,float z0,float z1)=>Enumerable.Range(0,Mathf.CeilToInt(Mathf.Abs(z1-z0))+1).Select(i=>new Point{x=x,z=Mathf.Lerp(z0,z1,i/Mathf.Max(1f,Mathf.CeilToInt(Mathf.Abs(z1-z0))))}).ToArray();
   routes.Add(new Route{name="Garage tractor exit",points=Line(-102,-101,-64)});routes.Add(new Route{name="Garage loader exit",points=Line(-94,-101,-64)});routes.Add(new Route{name="Fuel service approach",points=Line(-115,-64,-90)});routes.Add(new Route{name="Disposal internal approach",points=Line(94,-96,-84)});
   foreach(var route in routes)foreach(var p in route.points){var at=p.V;at.y=Ground(at)+2;var hits=Physics.OverlapBox(at,new Vector3(2.1f,1.6f,2.1f),Quaternion.identity,~0,QueryTriggerInteraction.Ignore).Where(Obstacle).ToArray();samples++;if(hits.Length>0){blocked++;report.AppendLine(route.name+" @ "+p.x+","+p.z+": "+string.Join("; ",hits.Select(c=>string.Join("/",Parents(c.transform).Select(t=>t.name).Reverse()))));}}
   report.Insert(0,"Conservative 4.2m-wide / 3.2m-high square swept envelope, bottom .4m above terrain. Samples="+samples+" blocked="+blocked+". Static diagnostic, not driving acceptance.\n");File.WriteAllText(Log+"/ClearanceAudit.txt",report.ToString());
  }
  static IEnumerable<Transform> Parents(Transform t){for(;t;t=t.parent)yield return t;}
  public static void Review(){scene=SceneManager.GetActiveScene();Check(scene.path==PathName&&!scene.isDirty&&!EditorApplication.isPlaying,"clean rebuilt Alps open");Validate(scene);Capture(scene);EditorSceneManager.OpenScene(PathName);}
  static void Capture(Scene s){terrainMesh=All<CatalogPlacement>(s).Single(p=>p.assetId=="alps-rebuild-terrainbase").GetComponentInChildren<MeshCollider>();var session=All<PrototypeSession>(s).Single();var rig=session.CameraRig;var camera=rig.view;bool hud=session.HUD.gameObject.activeSelf;var old=camera.targetTexture;var active=RenderTexture.active;var target=new GameObject("Temporary gameplay-camera audit target");var rt=RenderTexture.GetTemporary(1280,720,24);try{session.HUD.gameObject.SetActive(false);camera.targetTexture=rt;Directory.CreateDirectory(Log+"/Isometric");var sites=new List<(string,Vector3)>{("Town square",new Vector3(18,Ground(new Vector3(18,0,25)),25)),("Tower arch",new Vector3(0,Ground(new Vector3(0,0,78)),78)),("Garage",new Vector3(-103,SnowField.Ground,-97)),("Fuel",new Vector3(-117,SnowField.Ground,-80)),("Disposal",new Vector3(86,SnowField.Ground,-105))};foreach(var h in All<Transform>(s).Single(t=>t.name.StartsWith("04 Buildings")).Cast<Transform>())sites.Add((h.name.Split('|')[0].Trim(),h.position+new Vector3(-10,0,-10)));foreach(var site in sites){target.transform.position=site.Item2;rig.SetMode(CameraMode.Isometric);for(int i=0;i<120;i++)rig.UpdateForTarget(target.transform,.1f,true,8);Check(camera.orthographic&&Quaternion.Angle(camera.transform.rotation,Quaternion.Euler(41,45,0))<.01f,"actual isometric camera");camera.Render();RenderTexture.active=rt;var image=new Texture2D(1280,720,TextureFormat.RGB24,false);image.ReadPixels(new Rect(0,0,1280,720),0,0);image.Apply();File.WriteAllBytes(Log+"/Isometric/"+site.Item1+".png",image.EncodeToPNG());UnityEngine.Object.DestroyImmediate(image);}bool fog=RenderSettings.fog;RenderSettings.fog=false;camera.orthographic=true;camera.orthographicSize=680;camera.farClipPlane=3000;camera.layerCullDistances=new float[32];camera.useOcclusionCulling=false;camera.transform.SetPositionAndRotation(new Vector3(-750,1000,-750),Quaternion.Euler(41,45,0));camera.Render();RenderTexture.active=rt;var overview=new Texture2D(1280,720,TextureFormat.RGB24,false);overview.ReadPixels(new Rect(0,0,1280,720),0,0);overview.Apply();File.WriteAllBytes(Log+"/Overview.png",overview.EncodeToPNG());UnityEngine.Object.DestroyImmediate(overview);RenderSettings.fog=fog;}finally{session.HUD.gameObject.SetActive(hud);camera.targetTexture=old;RenderTexture.active=active;RenderTexture.ReleaseTemporary(rt);UnityEngine.Object.DestroyImmediate(target);}}
 }
